        ["sh.recycle.warning"] = new[] { "Alle Dateien im Papierkorb aller Laufwerke werden endgültig gelöscht und können danach nicht wiederhergestellt werden.", "All files in the recycle bins of all drives are deleted for good and cannot be restored afterwards.", "Todos los archivos de las papeleras de todas las unidades se borran para siempre y no se podrán recuperar.", "Todos os ficheiros das reciclagens de todas as unidades são apagados de vez e não podem ser restaurados.", "Все файлы в корзинах всех дисков будут удалены навсегда без возможности восстановления.", "所有驱动器回收站中的文件都将被永久删除，之后无法恢复。", "すべてのドライブのごみ箱内のファイルが完全に削除され、復元できなくなります。" },
        ["sh.recycle.failed"] = new[] { "Der Papierkorb konnte nicht vollständig geleert werden.", "The recycle bin could not be emptied completely.", "No se pudo vaciar la papelera por completo.", "Não foi possível esvaziar totalmente a reciclagem.", "Не удалось полностью очистить корзину.", "无法完全清空回收站。", "ごみ箱を完全には空にできませんでした。" },

